// Release 144 - adds Wait for It as a real, assignable entry in the classroom game-assignment flow, by extending the brain_games catalog table.
// discover band, focus self_management. Generated by server/scripts/build-core-games.js.
// reward_pipeline is left unset so it defaults to 'classroom_generic'; run seed-classroom-completion-badges.js separately to add its badge,
// and seed-brain-games-focus-values.js to confirm the focus.
//
// Safe to re-run: skipped if a row with this slug already exists.
require('dotenv').config({ path: require('path').join(__dirname, '..', '.env') });
const mysql = require('mysql2/promise');

async function main() {
  const conn = await mysql.createConnection({
    host: process.env.DB_HOST, port: Number(process.env.DB_PORT || 3306),
    user: process.env.DB_USER, password: process.env.DB_PASSWORD, database: process.env.DB_NAME,
  });

  const [[existing]] = await conn.query('SELECT id FROM brain_games WHERE slug = ?', ['wait-for-it']);
  if (existing) {
    console.log('Skipped: wait-for-it already in brain_games catalog (id=' + existing.id + ')');
  } else {
    const [[maxOrder]] = await conn.query('SELECT MAX(display_order) AS m FROM brain_games');
    await conn.query(
      `INSERT INTO brain_games (name, slug, description, icon, primary_skill, display_order, band, domain, casel_competencies, focus)
       VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
      [
        "Wait for It", 'wait-for-it',
        "Listen to a waiting problem, then pick what helps you wait.",
        '⏳', "Patience and Self-Control", (maxOrder?.m || 0) + 1,
        'discover', 'sel', 'self_management', 'self_management',
      ]
    );
    console.log('Added: wait-for-it to brain_games catalog');
  }

  await conn.end();
  console.log('Done.');
}

main().catch(err => { console.error(err); process.exit(1); });
